# Multigrain poll on the Pico: reads the module over SWD (swd.py) and decodes the same
# snapshot grainview_server.py serves at /state, so GRAINVIEW can run without the Mac.
# Addresses + decode rules: mg_map.py, generated by tools/gen_pico_map.py from the Mac
# tools. Check against the Mac's decode: tools/venv/bin/python tools/gv_pico.py poll
#
#   p = Poller(swd)       # a connected swd.SWD
#   snap = p.read()       # dict, same keys as /state (+ "pico_ms": poll time)
#   p.read(focus=True)    # only the selected sound (+ globals): the Pico UI's poll, ~1/4
#                         # of the time; the other sounds keep their last values
#   p.json()              # the last snapshot as JSON: a list of bytes pieces, to write one
#                         # after the other (no 15 KB block from a busy heap)
# Most of the state sits still between polls, so a sound (and the settings) is only
# decoded + JSON-encoded again when its raw bytes change.
import json
import struct
import time

import mg_map as M

GAP = 48                                      # merge reads closer than this
NAME_PEEK = 32                                # file name bytes read first (256 if no NUL)
RAM_SIZE = {"bool": 1, "enum": 1, "f32": 4, "quant": 2}
NBLK = M.BLOCK_HI - M.BLOCK_LO
START_OFF = M.PARAMS[0][1]                    # mod values are laid out like the params


def merge(wants):
    spans = []
    for a, n in sorted(set(wants)):
        if spans and a <= spans[-1][1] + GAP:
            if a + n > spans[-1][1]:
                spans[-1][1] = a + n
        else:
            spans.append([a, a + n])
    return [(lo, hi - lo) for lo, hi in spans]


class Spans:
    """Scattered reads as a few block reads (grainview_server.SpanReader)."""

    def __init__(self, s, spans):                 # spans sorted by address (merge())
        self.blocks = [(lo, s.read_block8(lo, n)) for lo, n in spans]
        self.los = [lo for lo, _ in spans]

    def get(self, a, n):
        los, i, j = self.los, 0, len(self.los)    # last block starting at <= a
        while j - i > 1:
            m = (i + j) >> 1
            if los[m] <= a:
                i = m
            else:
                j = m
        lo, b = self.blocks[i]
        if lo <= a and a + n <= lo + len(b):
            return b[a - lo:a - lo + n]
        raise KeyError(hex(a))

    def u8(self, a):
        return self.get(a, 1)[0]

    def u32(self, a):
        return struct.unpack("<I", self.get(a, 4))[0]

    def i32(self, a):
        return struct.unpack("<i", self.get(a, 4))[0]

    def f32(self, a):
        return struct.unpack("<f", self.get(a, 4))[0]

    def bitmap(self, a):                      # u32[2], bit n = slot n (bytewise: no bigints)
        b = self.get(a, 8)
        return [n for n in range(M.SLOTS) if b[n >> 3] >> (n & 7) & 1]


def base(n):
    return M.SOUND_BASE + n * M.SOUND_STRIDE


def name(b):
    b = b.split(b"\0", 1)[0]
    try:
        return b.decode()
    except UnicodeError:                      # latin-1, as the Mac side decodes it
        return "".join(chr(c) for c in b)


# ---- settings (grainview_server.read_settings / ram_decode) ----

def s_addr(row, n, i=4):
    return row[3] if row[3] is not None else base(n) + row[i]


def s_wants(sounds):
    w = []
    for row in M.SETTINGS:
        for n in sounds if row[0] == "sound" else (None,):
            w.append((s_addr(row, n), RAM_SIZE[row[2]]))
            if row[2] == "quant":
                w.append((s_addr(row, n, 5), 4))
    return w


def s_decode(row, sp, n):
    t, nopt, lo, hi, step, dp = row[2], row[6], row[7], row[8], row[9], row[10]
    a = s_addr(row, n)
    if t == "bool":
        return 1 if sp.u8(a) else 0
    if t == "enum":
        v = sp.u8(a)
        return v if v < nopt else None
    if t == "f32":
        v = sp.f32(a)
        if not lo - step <= v <= hi + step:  # also NaN
            return None
        return round(min(max(v, lo), hi), dp)
    if t == "quant":
        mask = struct.unpack("<H", sp.get(a, 2))[0]
        root = sp.u32(s_addr(row, n, 5))
        return {"notes": [bool(mask >> i & 1) for i in range(12)], "root": root if root < 12 else 0}
    return None


GLOBALS = ((M.CUR_SOUND, 1), (M.PLAYING, 4), (M.EDIT_SCENE, 1), (M.MORPH, 4),
           (M.SD_STATE, 4), (M.SIZE_MODE, 1), (M.SYNC, 1), (M.CLOCK_PERIOD, 4),
           (M.CUR_PROJECT, 1), (M.CUR_PRESET, 1), (M.PROJECT_EXISTS, 8),
           (M.PRESET_EXISTS, 8), (M.PRESET_LOCKED, 8)) + tuple((a, 4) for _, a in M.LIVE)
ALL = tuple(range(8))


class Poller:
    def __init__(self, s):
        self.s = s
        self.st, self.st_ms, self.st_for = None, 0, None
        self.st_graw = None                   # module / preset settings: raw bytes last decoded
        self.st_sraw = [None] * 8             # per sound: raw bytes + a version for its cache key
        self.st_sver = [0] * 8
        self.cache = [None] * 8               # per sound: (raw key, dict, JSON)
        self.snap = self.js = None
        self.spans, self.s_spans = {}, {}     # merged reads per set of sounds

    def spans_for(self, sounds):
        sp = self.spans.get(sounds)
        if sp is None:
            w = list(GLOBALS)
            for n in sounds:
                b = base(n)
                w += [(b + M.BLOCK_LO, NBLK), (b + M.SRC_OFF, 1), (b + M.LINK_RS, 1),
                      (b + M.LINK_SP, 1)]
            sp = self.spans[sounds] = merge(w)
        return sp

    def settings(self, sounds):
        """Re-read the settings of these sounds (+ module / preset); a group is decoded
        again only when its own bytes changed."""
        ss = self.s_spans.get(sounds)
        if ss is None:
            ss = self.s_spans[sounds] = merge(s_wants(sounds))
        sp = Spans(self.s, ss)
        st = self.st or {"module": {}, "preset": {}, "sounds": [{} for _ in range(8)]}
        glob = [r for r in M.SETTINGS if r[0] != "sound"]
        raw = tuple(sp.get(a, n) for a, n in s_wants(()))
        if raw != self.st_graw:
            self.st_graw = raw
            st = {"module": {}, "preset": {}, "sounds": st["sounds"]}
            for row in glob:
                st[row[0]][row[1]] = s_decode(row, sp, None)
        for n in sounds:
            raw = tuple(sp.get(a, k) for a, k in s_wants((n,)))
            if raw != self.st_sraw[n]:
                self.st_sraw[n], self.st_sver[n] = raw, self.st_sver[n] + 1
                st["sounds"][n] = {row[1]: s_decode(row, sp, n)
                                   for row in M.SETTINGS if row[0] == "sound"}
        return st

    def read(self, focus=False):
        t0 = time.ticks_ms()
        sounds = ALL
        if focus and None not in self.cache:
            sel = self.s.read_block8(M.CUR_SOUND, 1)[0]
            if sel < 8:
                sounds = (sel,)
        if (self.st is None or sounds != self.st_for
                or time.ticks_diff(t0, self.st_ms) >= M.SETTINGS_EVERY_MS):
            self.st, self.st_ms, self.st_for = self.settings(sounds), t0, sounds
        sp = Spans(self.s, self.spans_for(sounds))
        folders = {n: sp.u8(base(n) + M.SRC_OFF) for n in sounds}
        w = []
        for n, f in folders.items():          # file name + cursor follow the folder
            if f in M.FNAME_OFF:
                w += [(base(n) + M.FNAME_OFF[f], NAME_PEEK), (M.CURSORS + (f * 8 + n) * 4, 4)]
        sp2 = Spans(self.s, merge(w))
        sync = sp.u8(M.SYNC)
        out = []
        for n in range(8):
            if n not in folders:              # not read this time: as last read
                out.append(self.cache[n][1])
                continue
            folder, b = folders[n], base(n)
            known = folder in M.FNAME_OFF
            fname = cur = None
            if known:
                fname = sp2.get(b + M.FNAME_OFF[folder], NAME_PEEK)
                if b"\0" not in fname:
                    fname = self.s.read_block8(b + M.FNAME_OFF[folder], 0x100)
                cur = sp2.get(M.CURSORS + (folder * 8 + n) * 4, 4)
            key = (sp.get(b + M.BLOCK_LO, NBLK), folder, fname, cur,
                   sp.u8(b + M.LINK_RS), sp.u8(b + M.LINK_SP), self.st_sver[n], sync)
            c = self.cache[n]
            if c is None or c[0] != key:
                snd = self.sound(n, key)
                c = self.cache[n] = (key, snd, json.dumps(snd).encode())
            out.append(c[1])
        cp = sp.u8(M.CUR_PRESET)
        self.snap = {
            "mode": "swd", "connected": True, "error": None,
            "firmware": M.FW_VERSION,         # (main.py only shows a poll once it checked that)
            "selected": sp.u8(M.CUR_SOUND), "playing": sp.u32(M.PLAYING),
            "edit_scene": "B" if sp.u8(M.EDIT_SCENE) else "A",
            "morph": round(sp.f32(M.MORPH), 4),
            "sd_state": sp.u32(M.SD_STATE),
            "size_mode": sp.u8(M.SIZE_MODE), "sync": sync,
            "settings": {"module": self.st["module"], "preset": self.st["preset"]},
            "clock_period": round(sp.f32(M.CLOCK_PERIOD), 5),
            "live": {k: round(sp.f32(a), 4) for k, a in M.LIVE},
            "store": {"project": sp.u8(M.CUR_PROJECT), "projects": sp.bitmap(M.PROJECT_EXISTS),
                      "presets": sp.bitmap(M.PRESET_EXISTS), "locked": sp.bitmap(M.PRESET_LOCKED),
                      "preset": cp if cp < M.SLOTS else None},
            "sounds": out,
            "pico_ms": time.ticks_diff(time.ticks_ms(), t0),
        }
        self.js = None
        return self.snap

    def json(self):
        """The last snapshot as JSON pieces, spliced from the cached per-sound JSON."""
        if self.js is None:
            top = dict(self.snap)
            del top["sounds"]
            parts = [b'{"sounds": [']
            for i, c in enumerate(self.cache):
                parts += (b", ", c[2]) if i else (c[2],)
            self.js = parts + [b"], ", json.dumps(top)[1:].encode()]
        return self.js

    def sound(self, n, key):
        blk, folder, fname, cur, link_rs, link_sp, _, sync = key
        f = struct.unpack("<%df" % (NBLK // 4), blk)
        scenes, mod = {}, {}
        for sc in "AB":
            sb = M.SCENE_B if sc == "B" else 0
            scenes[sc] = {k: round(f[(o + sb - M.BLOCK_LO) // 4], 4) for k, o in M.PARAMS}
            mod[sc] = {src: {k: round(f[(sb + M.MOD_VALS + i * M.MOD_STRIDE + o - START_OFF
                                         - M.BLOCK_LO) // 4], 4) for k, o in M.PARAMS}
                       for src, i in M.MOD_SRC}
        known = folder in M.FNAME_OFF
        snd = {
            "folder": M.FOLDER_NAMES.get(folder), "A": scenes["A"], "B": scenes["B"],
            "mod": mod,
            "file": (name(fname) or None) if known else None,
            "cursor": struct.unpack("<i", cur)[0] if known else None,
            "link_rs": link_rs, "link_sp": link_sp,
        }
        st = dict(self.st["sounds"][n])
        st["link_rs"], st["link_sp"], st["sync"] = link_rs, link_sp, sync
        snd["settings"] = st
        return snd
